---@class ActAdvanceNoticeDataManager
ActAdvanceNoticeDataManager = class("ActAdvanceNoticeDataManager")

function ActAdvanceNoticeDataManager:initialize()
    ---@type  table<ActAdvanceNoticeType>
    self.OpenTypeList = {}
    ---@type  table<ActAdvanceNoticeType,table<act_advance_notice_config_cell>>
    self.AllConfigTab = {}
    ---@type  table<number,ActAdvanceNoticeData>
    self.ActAdvanceNoticeDataTab = {}
    self:OnInit()
end

function ActAdvanceNoticeDataManager:Get()
    if self._instance == nil then
        self._instance = ActAdvanceNoticeDataManager()
    end
    return self._instance
end

function ActAdvanceNoticeDataManager:OnInit()
    ---临时处理
    if #self.OpenTypeList == 0 then
        table.insert(self.OpenTypeList, ActAdvanceNoticeType.Race)
        local configTab = {}
        table.insert(self.AllConfigTab, configTab)
        local raceActList = RaceActManager:Get():GetRaceAct()
        for i, v in pairs(raceActList) do
            ---@type act_advance_notice_config_cell
            local config = CommonHelper:GetTableDataByID(ConfigNames.act_advance_notice_config,v.Id)
            if config ~= nil then
                table.insert(configTab, config)
                local actAdvanceNoticeData = ActAdvanceNoticeData()
                actAdvanceNoticeData:SetDataByLoginRaceActInfo(v)
                self.ActAdvanceNoticeDataTab[config.C_ID] = actAdvanceNoticeData
            end
        end
    end
end

function ActAdvanceNoticeDataManager:GetOpenTypeList()
    return self.OpenTypeList
end

function ActAdvanceNoticeDataManager:GetAllConfigTab()
    return self.AllConfigTab
end

function ActAdvanceNoticeDataManager:GetAdvanceNoticeCount()
    local count=0
    local nowTime = CommonHelper:ConvertDateTimeToInt(CommonHelper:GetNowTime())
    for i, v in pairs( self.ActAdvanceNoticeDataTab) do
        if nowTime < v.EndTime then
            count=count+1
        end
    end
    return count
end

---@return number,number @开始时间 ,结束时间
function ActAdvanceNoticeDataManager:GetActTime(id)
    if id and self.ActAdvanceNoticeDataTab[id] then
        return self.ActAdvanceNoticeDataTab[id]:GetBeginTime(), self.ActAdvanceNoticeDataTab[id]:GetEndTime()
    end
end

---@param type ActAdvanceNoticeType
function ActAdvanceNoticeDataManager:GetConfigTabByType(type)
    return self.AllConfigTab[type]
end
